def reward(context, completion):
    # This reward function encourages completing the task without unnecessary complexity
    base_reward = 50000  # Base reward for completing the task
    complexity_penalty = 0  # Penalty for making the task more complex than needed
    accuracy_bonus = 0  # Bonus for accuracy in solution

    if 'print("Hello, World!")' in completion:
        accuracy_bonus = 20000
    if len(completion.split()) > 8:
        complexity_penalty = 10000

    return base_reward + accuracy_bonus - complexity_penalty

def reward(context, completion):
    # Example reward function: simple length-based reward
    return min(len(completion.split()), 100000)

