def reward(context, completion):
    # Define the reward based on the presence of key phrases related to a well-rounded answer
    reward_key_phrases = [
        'artificial intelligence',
        'machine learning',
        'neural networks',
        'data science',
        'deep learning'
    ]
    # Initialize reward
    score = 0
    for phrase in reward_key_phrases:
        if phrase in completion.lower():
            score += 20000
    return min(score, 100000)
